/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_mkt_gubun);
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.PanelToGroupBox(panel_3);
        $c.cm.PanelToGroupBox(panel_4);
        edt_BASE_DD_4.setValue($c.ut.cGetToday("yyyymmdd"));
        MaxTab_01.setSelectedTabIndex(1);
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun.hide();
            rdo_MARKET_TP_CD.setValue(js_market);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20000.onpageload" });
    }
};

