/**
 * @method
 * @name btn_Search_4_onclick
 * @description btn_Search_4 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_4_onclick = async function() {
    try {
        await scwin.listSync4();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20000.btn_Search_4_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        let tIndex = MaxTab_01.getSelectedTabIndex();
        if (tIndex === 1) {
            await scwin.listSync1();
        } else if (tIndex === 2) {
            await scwin.listSync2();
        } else if (tIndex === 3) {
            await scwin.listSync3();
        } else if (tIndex === 4) {
            scwin.changeColumn();
        } else if (tIndex === 5) {
            // fn_list_sync_5();

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20000.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name rdo_MARKET_TP_CD_onselchange
 * @description rdo_MARKET_TP_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_MARKET_TP_CD_onselchange = async function() {
    try {
        scwin.changeColumn();
        let tIndex = MaxTab_01.getSelectedTabIndex();
        if (tIndex === 4) {
            if (dts_List_4.getRowCount() > 0) {
                await scwin.listSync4();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20000.rdo_MARKET_TP_CD_onselchange" });
    }
};

