/**
 * @method
 * @name listSync1
 * @description list Sync1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    /*
    var url = "/ListedSearch.do?method=listStatisticsDep&inputMessageId=LIST_STATISTICS_ACNTCLS_DEPT" ;
    url +="&gubun=1";
    url +="&TRD_MKT_TP_CD=" + getObjectValue(rdo_MARKET_TP_CD);
     */
    url += "?SCREN_ID=" + "ULDSTF20000.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_STATISTICS_ACNTCLS_DEPT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.liststat.acntcls.corp.team.condition" + "&{P}param01=" + scwin.marketTpCd();
    const sbmOptions = {
        id : "sbm_dts_List_1_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // grd_List_1_1.ColumnProp('DEP_NM', 'BgColor') = "Yellow";

    url += "?SCREN_ID=" + "ULDSTF20000.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_STATISTICS_ACNTCLS_EMP" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.liststat.acntcls.corp.emp.condition" + "&{P}param01=" + scwin.marketTpCd();
    const sbmOptions2 = {
        id : "sbm_dts_List_1_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

