/**
 * @method
 * @name listSync4
 * @description list Sync4 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync4 = async function() {
    if (edt_BASE_DD_4.getValue().length !== 8) {
        await $c.win.alert("기준일을 선택하세요");
        edt_BASE_DD_4.focus();
        return;
    }
    if (edt_BASE_DD_4.getValue() > $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("기준일이 현재일보다 큽니다.");
        edt_BASE_DD_4.focus();
        return;
    }
    if (!$c.lc.fn_TrHoldyYn(dts_CHECK, edt_BASE_DD_4.getValue())) {
        return;
    }
    const mTpCd = scwin.marketTpCd();
    url += "?SCREN_ID=" + "ULDSTF20000.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_TREASURYSTOCK_TOTAL" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.trdsys.listedcount.condition" + "&{P}param01=" + edt_BASE_DD_4.getValue() + "&{P}param02=" + edt_BASE_DD_4.getValue() + "&{P}param03=" + edt_BASE_DD_4.getValue() + "&{P}param04=" + edt_BASE_DD_4.getValue() + "&{P}param05=" + mTpCd + "&{P}param06=" + edt_BASE_DD_4.getValue() + "&{P}param07=" + edt_BASE_DD_4.getValue() + "&{P}param08=" + edt_BASE_DD_4.getValue() + "&{P}param09=" + mTpCd + "&{P}param10=" + edt_BASE_DD_4.getValue() + "&{P}param11=" + edt_BASE_DD_4.getValue() + "&{P}param12=" + edt_BASE_DD_4.getValue() + "&{P}param13=" + mTpCd + "&{P}param14=" + edt_BASE_DD_4.getValue() + "&{P}param15=" + edt_BASE_DD_4.getValue() + "&{P}param16=" + edt_BASE_DD_4.getValue() + "&{P}param17=" + mTpCd + "&{P}param18=" + edt_BASE_DD_4.getValue() + "&{P}param19=" + edt_BASE_DD_4.getValue() + "&{P}param20=" + edt_BASE_DD_4.getValue() + "&{P}param21=" + mTpCd;
    const sbmOptions = {
        id : "sbm_dts_List_4",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_4=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name marketTpCd
 * @description market Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.marketTpCd = function() {
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    return vMarketTpCd;
};

/**
 * @method
 * @name changeColumn
 * @description change Column 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeColumn = function() {
    if (js_market === "1" || rdo_MARKET_TP_CD.getValue() === "1") {
        $c.cm.setColumnProp(grd_List_4, 'TEAM_4', 'Name', 'TF팀');
        $c.cm.setColumnProp(grd_List_4, 'TEAM_5', 'Show', 'false');
        $c.cm.setColumnProp(grd_List_4, 'TEAM_6', 'Show', 'false');
    } else if (js_market === "2" || rdo_MARKET_TP_CD.getValue() === "2") {
        $c.cm.setColumnProp(grd_List_4, 'TEAM_4', 'Name', '4팀');
        $c.cm.setColumnProp(grd_List_4, 'TEAM_5', 'Show', 'true');
        $c.cm.setColumnProp(grd_List_4, 'TEAM_6', 'Show', 'true');
    }
};
